1	import { Email, Classification, Counterparty, EmailCategory } from './types';
2	
3	function extractDomain(email: string): string {
4	  const match = email.match(/@([^>]+)/);
5	  return match ? match[1].toLowerCase() : email.toLowerCase();
6	}
7	
8	function extractCompanyName(email: string, domain: string): string {
9	  // Try to extract from "Name <email>" format
10	  const nameMatch = email.match(/^"?([^"<]+)"?\s*</);
11	  if (nameMatch) {
12	    const name = nameMatch[1].trim();
13	    if (name && name !== domain) return name;
14	  }
15	  // Fall back to domain without TLD
16	  const parts = domain.split('.');
17	  if (parts.length >= 2) {
18	    return parts[0].charAt(0).toUpperCase() + parts[0].slice(1);
19	  }
20	  return domain;
21	}
22	
23	export function groupByCounterparty(
24	  emails: Email[],
25	  classifications: Classification[],
26	): Counterparty[] {
27	  const classMap = new Map(classifications.map(c => [c.emailId, c]));
28	  const domainGroups = new Map<string, { name: string; emails: Email[]; types: Map<EmailCategory, number> }>();
29	
30	  for (const email of emails) {
31	    const domain = extractDomain(email.from);
32	    if (!domainGroups.has(domain)) {
33	      domainGroups.set(domain, {
34	        name: extractCompanyName(email.from, domain),
35	        emails: [],
36	        types: new Map(),
37	      });
38	    }
39	    const group = domainGroups.get(domain)!;
40	    group.emails.push(email);
41	
42	    const cls = classMap.get(email.id);
43	    if (cls) {
44	      group.types.set(cls.category, (group.types.get(cls.category) || 0) + 1);
45	    }
46	  }
47	
48	  const counterparties: Counterparty[] = [];
49	  for (const [domain, group] of Array.from(domainGroups)) {
50	    counterparties.push({
51	      name: group.name,
52	      emailDomain: domain,
53	      emailCount: group.emails.length,
54	      emailTypes: Array.from(group.types.entries()).map(([type, count]) => ({ type, count })),
55	      emails: group.emails.map(e => e.id),
56	    });
57	  }
58	
59	  // Sort by email count descending
60	  counterparties.sort((a, b) => b.emailCount - a.emailCount);
61	  return counterparties;
62	}
